using Contoso.Services;

namespace Contoso.Services.Tests;

[TestClass]
public sealed class ServiceRegistryTests
{
    [TestMethod]
    public void Register_ThenResolve_ReturnsSameInstance()
    {
        // Arrange
        var registry = new ServiceRegistry();
        var service = new FakeService();

        // Act
        registry.Register<IFakeService>(service);
        var resolved = registry.Resolve<IFakeService>();

        // Assert
        Assert.AreSame(service, resolved);
    }

    [TestMethod]
    public void Resolve_UnregisteredService_ReturnsNull()
    {
        // Arrange
        var registry = new ServiceRegistry();

        // Act
        var resolved = registry.Resolve<IFakeService>();

        // Assert
        Assert.IsNull(resolved);
    }

    [TestMethod]
    public void GetAll_ContainsRegisteredService()
    {
        // Arrange
        var registry = new ServiceRegistry();
        var service = new FakeService();
        registry.Register<IFakeService>(service);

        // Act
        var all = registry.GetAll();

        // Assert
        Assert.Contains(service, all);
    }

    [TestMethod]
    public void GetAll_DoesNotContainRemovedService()
    {
        // Arrange
        var registry = new ServiceRegistry();
        var service = new FakeService();
        registry.Register<IFakeService>(service);
        registry.Remove<IFakeService>();

        // Act
        var all = registry.GetAll();

        // Assert
        Assert.DoesNotContain(service, all);
    }

    [TestMethod]
    public void GetAll_BeforeAnyRegistration_IsEmpty()
    {
        // Arrange
        var registry = new ServiceRegistry();

        // Act
        var all = registry.GetAll();

        // Assert
        Assert.IsEmpty(all);
    }

    [TestMethod]
    public void GetAll_AfterRegistration_IsNotEmpty()
    {
        // Arrange
        var registry = new ServiceRegistry();
        registry.Register<IFakeService>(new FakeService());

        // Act
        var all = registry.GetAll();

        // Assert
        Assert.IsNotEmpty(all);
    }

    private interface IFakeService;
    private sealed class FakeService : IFakeService;
}

